/// The `ld ra; addiu sp; jr ra` tail.
pub(crate) fn peak_unlock_tail(c: &mut Cpu, frame: Frame) -> Flow {
    c.cycles += 2;
    frame.restore_ra(c, 0);
    frame.close(c);
    Ok(())
}

/// A `gp_6`-relative global.
