/// `s0`..`s7` and the like: the low word of a callee-saved register.
#[inline]
pub(crate) fn oc944_r(c: &Cpu, reg: usize) -> u32 {
    c.g[reg][0] as u32
}

/// The `sUISound` message call of the popup: `p = *(owner + 0x14)`, falling
/// back to the global sound object in `s4`; `p->vt[2](p, msg)` when `p != 0`.
/// `first` is the block charge before the lookups, `ret` the return address.
pub(crate) fn oc944_sound(c: &mut Cpu, msg: u64, first: u64, ret: u32) -> Flow {
    c.cycles += first;
    let s1 = oc944_r(c, S1);
    let owner = Addr(s1.wrapping_add(0x10)).lw(c);
    c.g[V0][0] = owner;
    c.g[A2][0] = Addr((owner as u32).wrapping_add(0x14)).lw(c);
    if c.g[A2][0] == 0 {
        c.g[A2][0] = c.g[S4][0];
    }
    let none = c.g[A2][0] == 0;
    c.g[A1][0] = msg;
    if !none {
        c.cycles += 5;
        let p = oc944_r(c, A2);
        let vt = Addr(p).lw(c);
        c.g[V0][0] = vt;
        c.g[A0][0] = Addr((vt as u32).wrapping_add(0x10)).lh(c);
        let f = Addr((vt as u32).wrapping_add(0x14)).lw(c);
        c.g[V1][0] = f;
        c.g[A0][0] = sx(p.wrapping_add(oc944_r(c, A0)));
        call_ptr(c, f as u32, ret)?;
    }
    Ok(())
}

/// A virtual call on the input object `s0`: `v1 = in->vt`; `a0 = s0 + vt[off]`
/// (halfword delta), call `vt[off + 4]`.
pub(crate) fn oc944_vcall(c: &mut Cpu, off: u32, ret: u32) -> Flow {
    let s0 = oc944_r(c, S0);
    let vt = Addr(s0.wrapping_add(8)).lw(c);
    c.g[V1][0] = vt;
    c.g[A0][0] = Addr((vt as u32).wrapping_add(off)).lh(c);
    let f = Addr((vt as u32).wrapping_add(off + 4)).lw(c);
    c.g[V0][0] = f;
    c.g[A0][0] = sx(s0.wrapping_add(oc944_r(c, A0)));
    call_ptr(c, f as u32, ret)
}

/// `cFEPopupScreenPos_Update` (0x1df050): the screen-position popup (the
/// "adjust the picture" calibration). For each pad `i` in 0..2 (until one
/// reports activity): accept (pad 5, sound 6, accepted = 1) or cancel (pad 6,
/// sound 3, accepted = 0) set flag `0x80` and call `func_0039f190(owner + 0x18, 1)`;
/// the four direction pads move `x`/`y` by one and play the matching frame; then
/// the position is clamped to +-20 (sound 4 when it was outside) and handed to
/// the renderer's slot 12 (`*(gp - 0x854) + 0x10d8`).
pub fn cfe_popup_screen_pos_update(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 14;
        let frame = Frame::open(c, 0x60);
        frame.save(c, S1, 0x40);
        frame.save(c, S2, 0x30);
        c.g[S1][0] = c.g[A0][0];
        frame.save(c, S3, 0x20);
        c.g[S2][0] = 0;
        frame.save(c, S4, 0x10);
        c.g[S3][0] = 0xffff;
        frame.save(c, S0, 0x50);
        c.g[S4][0] = sx(oc944_r(c, GP).wrapping_add(0x2968));
        frame.save_ra(c, 0);
        let s1 = oc944_r(c, S1);
        let owner = Addr(s1.wrapping_add(0x10)).lw(c);
        c.g[V0][0] = owner;
        c.g[S0][0] = Addr((owner as u32).wrapping_add(0xc)).lw(c);
        c.g[V0][0] = Addr(oc944_r(c, S0).wrapping_add(8)).lw(c);
        'iter: loop {
            // pad->vt[44](pad, i)
            c.cycles += 12;
            c.g[A1][0] = c.g[S2][0] & 0xff;
            let vt = oc944_r(c, V0);
            c.g[A0][0] = Addr(vt.wrapping_add(0x160)).lh(c);
            c.g[A2][0] = Addr(vt.wrapping_add(0x164)).lw(c);
            let f = oc944_r(c, A2);
            c.g[A0][0] = sx(oc944_r(c, S0).wrapping_add(oc944_r(c, A0)));
            call_ptr(c, f, 0x001d_f09c)?;
            // if (pad->vt[40](pad) == 0) continue
            oc944_vcall(c, 0x140, 0x001d_f0b0)?;
            if c.g[V0][0] == 0 {
                c.g[S2][0] = sx(oc944_r(c, S2).wrapping_add(1));
            } else {
                oc944_handle_pad(c)?;
                frame.restore(c, S0, 0x50);
                break 'iter;
            }
            c.cycles += 3;
            c.g[V0][0] = ((c.g[S2][0] as i64) < 2) as u64;
            if c.g[V0][0] != 0 {
                c.g[V0][0] = Addr(oc944_r(c, S0).wrapping_add(8)).lw(c);
                if event_due(c) {
                    deliver_event_here(c, 0x001d_f088);
                }
                continue 'iter;
            } else {
                c.cycles += 1;
                frame.restore(c, S0, 0x50);
                break 'iter;
            }
        }
        c.cycles += 7;
        frame.restore(c, S4, 0x10);
        frame.restore(c, S3, 0x20);
        frame.restore(c, S2, 0x30);
        frame.restore(c, S1, 0x40);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// The part of the update after pad `i` reported input: the buttons, the
/// clamp and the renderer call. Ends with `s0` still to be restored by the
/// caller (the generated `lq s0` sits after the renderer call).
pub(crate) fn oc944_handle_pad(c: &mut Cpu) -> Flow {
    c.cycles += 7;
    let s0 = oc944_r(c, S0);
    c.g[V1][0] = Addr(s0.wrapping_add(8)).lw(c);
    c.g[A0][0] = Addr(oc944_r(c, V1).wrapping_add(0x28)).lh(c);
    let f = Addr(oc944_r(c, V1).wrapping_add(0x2c)).lw(c);
    c.g[V0][0] = f;
    c.g[A0][0] = sx(s0.wrapping_add(oc944_r(c, A0)));
    call_ptr(c, f as u32, 0x001d_f0cc)?;
    let mut done = false;
    if c.g[V0][0] != 0 {
        // accept: sound 6, accepted = 1
        oc944_sound(c, 6, 5, 0x001d_f0fc)?;
        c.cycles += 7;
        let s1 = oc944_r(c, S1);
        c.g[V0][0] = Addr(s1.wrapping_add(0x1c)).lw(c);
        c.g[V1][0] = 1;
        c.g[A0][0] = Addr(s1.wrapping_add(0x10)).lw(c);
        c.g[A1][0] = 1;
        c.g[V0][0] |= 0x80;
        let v1 = c.g[V1][0];
        Addr(s1.wrapping_add(0x50)).sb(c, v1);
        oc944_notify(c)?;
        done = true;
    } else {
        c.g[V1][0] = Addr(oc944_r(c, S0).wrapping_add(8)).lw(c);
        c.cycles += 6;
        let v1 = oc944_r(c, V1);
        c.g[A0][0] = Addr(v1.wrapping_add(0x30)).lh(c);
        let f = Addr(v1.wrapping_add(0x34)).lw(c);
        c.g[V0][0] = f;
        c.g[A0][0] = sx(oc944_r(c, S0).wrapping_add(oc944_r(c, A0)));
        call_ptr(c, f as u32, 0x001d_f128)?;
        if c.g[V0][0] != 0 {
            // cancel: sound 3, accepted = 0
            oc944_sound(c, 3, 5, 0x001d_f158)?;
            c.cycles += 5;
            let s1 = oc944_r(c, S1);
            c.g[V0][0] = Addr(s1.wrapping_add(0x1c)).lw(c);
            c.g[A1][0] = 1;
            c.g[A0][0] = Addr(s1.wrapping_add(0x10)).lw(c);
            c.g[V0][0] |= 0x80;
            Addr(s1.wrapping_add(0x50)).sb(c, 0);
            oc944_notify(c)?;
            done = true;
        } else {
            c.g[V1][0] = Addr(oc944_r(c, S0).wrapping_add(8)).lw(c);
        }
    }
    if !done {
        oc944_direction(c)?;
    }
    oc944_clamp_and_report(c)
}

/// Store the flags and call `func_0039f190(owner + 0x18, 1)`; then reload `x`.
pub(crate) fn oc944_notify(c: &mut Cpu) -> Flow {
    c.cycles += 5;
    let s1 = oc944_r(c, S1);
    let v0 = c.g[V0][0];
    Addr(s1.wrapping_add(0x1c)).sw(c, v0);
    c.g[A0][0] = sx(oc944_r(c, A0).wrapping_add(0x18));
    call_ptr(c, 0x0039_f190, 0x001d_f178)?;
    c.g[V0][0] = Addr(oc944_r(c, S1).wrapping_add(0x48)).lw(c);
    Ok(())
}

/// The "play the move animation" tail of a direction pad: `a0` holds the
/// label string; `frame = getFrameByLabel(screen, hash(label))`, then
/// `playFrame(screen, frame, 1)` unless the frame is `0xffff`. Then `v0 = x`.
/// `rets` are the three return addresses, `charges` the block charges before
/// the hash call and before the play call, `tail` the extra charge of the
/// play path before it rejoins.
pub(crate) fn oc944_play(c: &mut Cpu, rets: [u32; 3], charges: [u64; 2], tail: u64) -> Flow {
    c.cycles += charges[0];
    call_ptr(c, 0x0031_7670, rets[0])?;
    c.g[A0][0] = Addr(oc944_r(c, S1).wrapping_add(0x40)).lw(c);
    c.g[A1][0] = c.g[V0][0];
    call_ptr(c, 0x0039_c778, rets[1])?;
    let same = c.g[V0][0] == c.g[S3][0];
    c.g[A1][0] = c.g[V0][0];
    if same {
        c.cycles += 1;
    } else {
        c.cycles += charges[1];
        c.g[A0][0] = Addr(oc944_r(c, S1).wrapping_add(0x40)).lw(c);
        c.g[A2][0] = 1;
        call_ptr(c, 0x0039_c870, rets[2])?;
        c.cycles += tail;
    }
    c.g[V0][0] = Addr(oc944_r(c, S1).wrapping_add(0x48)).lw(c);
    Ok(())
}

/// One direction pad's virtual call (`v1` = the pad's vtable): block charge 6,
/// `vt[off]` / `vt[off + 4]`, result in `v0`.
pub(crate) fn oc944_dir_call(c: &mut Cpu, off: u32, ret: u32) -> Flow {
    c.cycles += 6;
    let v1 = oc944_r(c, V1);
    c.g[A0][0] = Addr(v1.wrapping_add(off)).lh(c);
    let f = Addr(v1.wrapping_add(off + 4)).lw(c);
    c.g[V0][0] = f;
    c.g[A0][0] = sx(oc944_r(c, S0).wrapping_add(oc944_r(c, A0)));
    call_ptr(c, f as u32, ret)
}

/// Reload `v1 = pad->vt` after a direction pad that reported nothing.
pub(crate) fn oc944_reload_vt(c: &mut Cpu) {
    c.g[V1][0] = Addr(oc944_r(c, S0).wrapping_add(8)).lw(c);
}

/// The four direction pads: 19 = x-1 (string `0x4a1550`), 20 = x+1
/// (`0x45ddf0`), 17 = y+1 (`0x4a1558`), 18 = y-1 (`0x4a1560`); the first that
/// fires changes the position and plays its frame. Leaves `v0 = x`.
pub(crate) fn oc944_direction(c: &mut Cpu) -> Flow {
    let s1 = oc944_r(c, S1);
    oc944_dir_call(c, 0x98, 0x001d_f190)?;
    if c.g[V0][0] != 0 {
        c.cycles += 6;
        c.g[V0][0] = Addr(s1.wrapping_add(0x48)).lw(c);
        c.g[A0][0] = sx(0x4a_0000u32.wrapping_add(0x1550));
        c.g[V0][0] = sx(oc944_r(c, V0).wrapping_sub(1));
        let v0 = c.g[V0][0];
        Addr(s1.wrapping_add(0x48)).sw(c, v0);
        return oc944_play(c, [0x001d_f214, 0x001d_f220, 0x001d_f234], [7, 5], 0);
    }
    oc944_reload_vt(c);
    oc944_dir_call(c, 0xa0, 0x001d_f1c0)?;
    if c.g[V0][0] != 0 {
        c.cycles += 6;
        c.g[V0][0] = Addr(s1.wrapping_add(0x48)).lw(c);
        c.g[A0][0] = sx(0x46_0000u32.wrapping_sub(0x2210));
        c.g[V0][0] = sx(oc944_r(c, V0).wrapping_add(1));
        let v0 = c.g[V0][0];
        Addr(s1.wrapping_add(0x48)).sw(c, v0);
        return oc944_play(c, [0x001d_f214, 0x001d_f220, 0x001d_f234], [7, 5], 0);
    }
    oc944_reload_vt(c);
    oc944_dir_call(c, 0x88, 0x001d_f1f0)?;
    if c.g[V0][0] != 0 {
        c.cycles += 5;
        c.g[V0][0] = Addr(s1.wrapping_add(0x4c)).lw(c);
        c.g[A0][0] = sx(0x4a_0000u32.wrapping_add(0x1558));
        c.g[V0][0] = sx(oc944_r(c, V0).wrapping_add(1));
        let v0 = c.g[V0][0];
        Addr(s1.wrapping_add(0x4c)).sw(c, v0);
        return oc944_play(c, [0x001d_f214, 0x001d_f220, 0x001d_f234], [7, 5], 0);
    }
    oc944_reload_vt(c);
    oc944_dir_call(c, 0x90, 0x001d_f24c)?;
    c.g[A0][0] = 0x4a_0000;
    if c.g[V0][0] == 0 {
        c.cycles += 1;
        c.g[V0][0] = Addr(s1.wrapping_add(0x48)).lw(c);
        return Ok(());
    }
    c.cycles += 10;
    c.g[V0][0] = Addr(s1.wrapping_add(0x4c)).lw(c);
    c.g[A0][0] = sx(oc944_r(c, A0).wrapping_add(0x1560));
    c.g[V0][0] = sx(oc944_r(c, V0).wrapping_sub(1));
    let v0 = c.g[V0][0];
    Addr(s1.wrapping_add(0x4c)).sw(c, v0);
    oc944_play(c, [0x001d_f268, 0x001d_f274, 0x001d_f288], [0, 3], 1)
}

/// Clamp `x`/`y` to +-20 (sound 4 when either was outside) and call the
/// renderer's slot 12 with them. `v0 = x` on entry.
pub(crate) fn oc944_clamp_and_report(c: &mut Cpu) -> Flow {
    let s1 = oc944_r(c, S1);
    c.cycles += 4;
    c.g[V0][0] = sx(oc944_r(c, V0).wrapping_add(0x14));
    c.g[V0][0] = (c.g[V0][0] < 0x29) as u64;
    let mut sound = false;
    if c.g[V0][0] == 0 {
        sound = true;
    } else {
        c.cycles += 4;
        c.g[V1][0] = Addr(s1.wrapping_add(0x4c)).lw(c);
        c.g[V0][0] = ((c.g[V1][0] as i64) < -20) as u64;
        if c.g[V0][0] != 0 {
            sound = true;
        } else {
            c.cycles += 3;
            c.g[V0][0] = ((c.g[V1][0] as i64) < 21) as u64;
            if c.g[V0][0] != 0 {
                c.g[V1][0] = Addr(s1.wrapping_add(0x48)).lw(c);
            } else {
                c.cycles += 1;
                sound = true;
            }
        }
    }
    if sound {
        oc944_sound(c, 4, 4, 0x001d_f2e0)?;
        c.cycles += 1;
        c.g[V1][0] = Addr(s1.wrapping_add(0x48)).lw(c);
    }
    // x = clamp(x, -20, 20)
    c.cycles += 3;
    c.g[V0][0] = ((c.g[V1][0] as i64) < -20) as u64;
    let low = c.g[V0][0] != 0;
    c.g[A0][0] = 0x14;
    if low {
        c.cycles += 1;
        c.g[V1][0] = 0xffff_ffff_ffff_ffec;
    } else {
        c.cycles += 3;
        c.g[V0][0] = ((c.g[A0][0] as i64) < (c.g[V1][0] as i64)) as u64;
        if c.g[V0][0] != 0 {
            c.g[V1][0] = c.g[A0][0];
        }
    }
    // y = clamp(y, -20, 20); x stored in the delay slot of the first compare
    c.cycles += 5;
    c.g[A2][0] = Addr(s1.wrapping_add(0x4c)).lw(c);
    c.g[A0][0] = 0x14;
    c.g[V0][0] = ((c.g[A2][0] as i64) < -20) as u64;
    let low = c.g[V0][0] != 0;
    let v1 = c.g[V1][0];
    Addr(s1.wrapping_add(0x48)).sw(c, v1);
    if low {
        c.cycles += 1;
        c.g[A2][0] = 0xffff_ffff_ffff_ffec;
    } else {
        c.cycles += 3;
        c.g[V0][0] = ((c.g[A0][0] as i64) < (c.g[A2][0] as i64)) as u64;
        if c.g[V0][0] != 0 {
            c.g[A2][0] = c.g[A0][0];
        }
    }
    c.cycles += 10;
    let a2 = c.g[A2][0];
    Addr(s1.wrapping_add(0x4c)).sw(c, a2);
    let a3 = Addr(oc944_r(c, GP).wrapping_sub(0x854)).lw(c);
    c.g[A3][0] = a3;
    c.g[A1][0] = Addr(s1.wrapping_add(0x48)).lw(c);
    let vt = Addr((a3 as u32).wrapping_add(0x10d8)).lw(c);
    c.g[V0][0] = vt;
    c.g[A0][0] = Addr((vt as u32).wrapping_add(0x60)).lh(c);
    let f = Addr((vt as u32).wrapping_add(0x64)).lw(c);
    c.g[V1][0] = f;
    c.g[A0][0] = sx((a3 as u32).wrapping_add(oc944_r(c, A0)));
    call_ptr(c, f as u32, 0x001d_f344)
}

/// Callees of this module's bodies (all reached through `call_indirect`).
pub(crate) const STR_HASH: u32 = 0x0031_7670;

// GetHashValue32(char*)
pub(crate) const ADD_SCREEN: u32 = 0x0039_7cc0;

// cUIEngine_addScreenByHashName
pub(crate) const PLAY_FRAME: u32 = 0x0039_c870;

// cUIScreen_playFrame
pub(crate) const FIND_OBJECT: u32 = 0x0039_d860;

// cUIScreen_getObjectByHashName
pub(crate) const SET_TEXT_ID: u32 = 0x003a_1000;

// cUIText_setUnicodeStringByID
pub(crate) const UI_STATE_CTOR: u32 = 0x0039_e2a0;

// UIState_ctor
pub(crate) const UI_STATE_DTOR: u32 = 0x0039_e390;

// UIState_dtor
pub(crate) const NET_FE_STATE_CTOR: u32 = 0x001a_8500;

// NetFEState_ctor
pub(crate) const INIT_PLAYER_ROWS: u32 = 0x0019_26f0;

// cFEStateBraggingRights_InitPlayerRows

/// `void cFEPopupVideoCalibration_Init(self)` (0x1deb90; the reference name is
/// `cFEPopupVideoCalibration_onCreateScreen`): open the calibration screen
/// (`self+0x40`) by its hash name, play one frame of it, show its title and
/// clear the "shown" flag at `self+0x48`.
pub fn cfe_popup_video_calibration_init(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 16;
        let frame = Frame::open(c, 0x30);
        frame.save(c, S1, 0x10);
        c.g[S1][0] = c.g[A0][0];
        frame.save_ra(c, 0);
        frame.save(c, S0, 0x20);
        // The screen: GetHashValue32(D_004A1548), then addScreen(engine, self, hash, 0).
        c.g[A0][0] = sx(0x004a_1548);
        c.g[S0][0] = Addr(r32(c, S1).wrapping_add(0x10)).lw(c);
        call_ptr(c, STR_HASH, 0x001d_ebb4)?;
        c.g[A0][0] = c.g[S0][0];
        c.g[A2][0] = c.g[V0][0];
        c.g[A1][0] = c.g[S1][0];
        c.g[A3][0] = 0;
        call_ptr(c, ADD_SCREEN, 0x001d_ebc8)?;
        let no_screen = c.g[V0][0] == 0;
        let value = c.g[V0][0];
        Addr(r32(c, S1).wrapping_add(0x40)).sw(c, value);
        if !no_screen {
            c.cycles += 4;
            c.g[A0][0] = c.g[V0][0];
            c.g[A1][0] = 0;
            c.g[A2][0] = 0;
            call_ptr(c, PLAY_FRAME, 0x001d_ebe0)?;
        }
        // The title widget: setVisible(1).
        c.cycles += 8;
        c.g[A0][0] = Addr(r32(c, GP).wrapping_sub(0x1bb0)).lw(c);
        call_ptr(c, STR_HASH, 0x001d_ebe8)?;
        calibration_find_screen_widget(c, 0x001d_ebf4)?;
        c.g[A2][0] = c.g[V0][0];
        c.g[A1][0] = 1;
        if c.g[A2][0] != 0 {
            popup_call_method48(c, 0x001d_ec14)?;
        }
        // The title text.
        c.cycles += 9;
        c.g[A0][0] = sx(0x0045_dd90);
        call_ptr(c, STR_HASH, 0x001d_ec20)?;
        calibration_find_screen_widget(c, 0x001d_ec2c)?;
        c.g[S0][0] = c.g[V0][0];
        c.g[A0][0] = 0x0046_0000;
        if c.g[S0][0] != 0 {
            c.cycles += 5;
            c.g[A0][0] = sx(0x0045_dda0);
            call_ptr(c, STR_HASH, 0x001d_ec40)?;
            c.g[A0][0] = c.g[S0][0];
            c.g[A1][0] = c.g[V0][0];
            call_ptr(c, SET_TEXT_ID, 0x001d_ec4c)?;
        }
        c.cycles += 6;
        Addr(r32(c, S1).wrapping_add(0x48)).sb(c, 0);
        frame.restore(c, S0, 0x20);
        frame.restore(c, S1, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    });
}

/// `int cFEPopupVideoCalibration_HandleInput(self, w)` (0x1dec68; the
/// reference name is `func_001DEC68`): when the widget's `vt[5]` method
/// answers, show the calibration popup the first time (or refresh its
/// position on later calls), then play its sound. Returns 1.
pub fn cfe_popup_video_calibration_handle_input(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 12;
        let frame = Frame::open(c, 0x30);
        frame.save(c, S1, 0x10);
        frame.save(c, S0, 0x20);
        c.g[S1][0] = c.g[A0][0];
        frame.save_ra(c, 0);
        // w->vt[5].fn(w + delta)
        c.g[V1][0] = Addr(r32(c, A1).wrapping_add(8)).lw(c);
        c.g[A0][0] = Addr(r32(c, V1).wrapping_add(0x28)).lh(c);
        c.g[V0][0] = Addr(r32(c, V1).wrapping_add(0x2c)).lw(c);
        let widget_method = r32(c, V0);
        c.g[A0][0] = sx(r32(c, A1).wrapping_add(r32(c, A0)));
        call_ptr(c, widget_method, 0x001d_ec90)?;
        frame.restore(c, S0, 0x20);
        if c.g[V0][0] != 0 {
            calibration_popup_body(c, frame)?;
        }
        c.cycles += 5;
        c.g[V0][0] = 1;
        frame.restore(c, S1, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    });
}

/// The part of `HandleInput` that runs when the widget answered: the
/// "shown" flag at `self+0x48` decides between a refresh of the popup flags
/// and the first show, then the popup's sound plays (`self+0x10 -> +0x14`,
/// or the default sound object at `gp+0x2968`).
pub(crate) fn calibration_popup_body(c: &mut Cpu, frame: Frame) -> Flow {
    c.cycles += 3;
    c.g[V0][0] = Addr(r32(c, S1).wrapping_add(0x48)).lb(c);
    if c.g[V0][0] != 0 {
        c.g[V0][0] = Addr(r32(c, S1).wrapping_add(0x1c)).lw(c);
        c.cycles += 5;
        c.g[V1][0] = 0xffff_ffff_ffff_c0ff;
        c.g[V0][0] |= 0x80;
        c.g[V0][0] &= c.g[V1][0];
        c.g[V0][0] |= 0x700;
        let value = c.g[V0][0];
        Addr(r32(c, S1).wrapping_add(0x1c)).sw(c, value);
    } else {
        calibration_show_1bb0(c)?;
        calibration_show_1bac(c)?;
        calibration_title_text(c)?;
        calibration_show_45ddc8(c)?;
        c.cycles += 3;
        c.g[V0][0] = 1;
        let value = c.g[V0][0];
        Addr(r32(c, S1).wrapping_add(0x48)).sb(c, value);
    }
    // The popup's sound: sound->vt[2].fn(sound + delta, 6).
    c.cycles += 6;
    c.g[V0][0] = Addr(r32(c, S1).wrapping_add(0x10)).lw(c);
    c.g[V1][0] = sx(r32(c, GP).wrapping_add(0x2968));
    c.g[A2][0] = Addr(r32(c, V0).wrapping_add(0x14)).lw(c);
    if c.g[A2][0] == 0 {
        c.g[A2][0] = c.g[V1][0];
    }
    c.g[A1][0] = 6;
    if c.g[A2][0] != 0 {
        c.cycles += 5;
        c.g[V0][0] = Addr(r32(c, A2)).lw(c);
        c.g[A0][0] = Addr(r32(c, V0).wrapping_add(0x10)).lh(c);
        c.g[V1][0] = Addr(r32(c, V0).wrapping_add(0x14)).lw(c);
        let sound_method = r32(c, V1);
        c.g[A0][0] = sx(r32(c, A2).wrapping_add(r32(c, A0)));
        call_ptr(c, sound_method, 0x001d_edd0)?;
    }
    c.cycles += 1;
    frame.restore(c, S0, 0x20);
    Ok(())
}

/// `GetHashValue32` of the global at `gp-0x1bb0`, the screen's widget of that
/// name, and when found its method with a1 = 0 (`show_EC68(self, name, 0)`).
pub(crate) fn calibration_show_1bb0(c: &mut Cpu) -> Flow {
    c.cycles += 8;
    c.g[A0][0] = Addr(r32(c, GP).wrapping_sub(0x1bb0)).lw(c);
    call_ptr(c, STR_HASH, 0x001d_ecac)?;
    calibration_find_screen_widget(c, 0x001d_ecb8)?;
    c.g[A2][0] = c.g[V0][0];
    c.g[A1][0] = 0;
    if c.g[A2][0] != 0 {
        popup_call_method48(c, 0x001d_ecd8)?;
    }
    Ok(())
}

/// `show_EC68(self, gp-0x1bac name, 1)`: the same lookup with a1 = 1.
pub(crate) fn calibration_show_1bac(c: &mut Cpu) -> Flow {
    c.cycles += 9;
    c.g[A0][0] = Addr(r32(c, GP).wrapping_sub(0x1bac)).lw(c);
    call_ptr(c, STR_HASH, 0x001d_ece4)?;
    calibration_find_screen_widget(c, 0x001d_ecf0)?;
    c.g[A2][0] = c.g[V0][0];
    c.g[A1][0] = 1;
    if c.g[A2][0] != 0 {
        popup_call_method48(c, 0x001d_ed10)?;
    }
    Ok(())
}

/// The title text: `cUIText_setUnicodeStringByID(text, hash(D_0045DDB8))`
/// when the widget `D_0045DD90` exists.
pub(crate) fn calibration_title_text(c: &mut Cpu) -> Flow {
    c.cycles += 9;
    c.g[A0][0] = sx(0x0045_dd90);
    call_ptr(c, STR_HASH, 0x001d_ed1c)?;
    calibration_find_screen_widget(c, 0x001d_ed28)?;
    c.g[S0][0] = c.g[V0][0];
    if c.g[S0][0] == 0 {
        c.g[A0][0] = 0x0046_0000;
    } else {
        c.cycles += 7;
        c.g[A0][0] = 0x0046_0000;
        c.g[A0][0] = sx(0x0045_ddb8);
        call_ptr(c, STR_HASH, 0x001d_ed40)?;
        c.g[A0][0] = c.g[S0][0];
        c.g[A1][0] = c.g[V0][0];
        call_ptr(c, SET_TEXT_ID, 0x001d_ed4c)?;
        c.g[A0][0] = 0x0046_0000;
    }
    Ok(())
}

/// `show_EC68(self, D_0045DDC8, 0)`: the last of the four popup steps.
pub(crate) fn calibration_show_45ddc8(c: &mut Cpu) -> Flow {
    c.cycles += 8;
    c.g[A0][0] = sx(0x0045_ddc8);
    call_ptr(c, STR_HASH, 0x001d_ed58)?;
    calibration_find_screen_widget(c, 0x001d_ed64)?;
    c.g[A2][0] = c.g[V0][0];
    c.g[A1][0] = 0;
    if c.g[A2][0] != 0 {
        popup_call_method48(c, 0x001d_ed84)?;
    }
    Ok(())
}

/// `cUIScreen_getObjectByHashName(self->screen (+0x40), a1 = the hash in v0)`,
/// returning to `ret`. The caller sets a2 from v0 where the code does.
pub(crate) fn calibration_find_screen_widget(c: &mut Cpu, ret: u32) -> Flow {
    c.g[A0][0] = Addr(r32(c, S1).wrapping_add(0x40)).lw(c);
    c.g[A1][0] = c.g[V0][0];
    call_ptr(c, FIND_OBJECT, ret)
}

/// The method at vtable slot 0x48 of the object in a2 (`cycles 5`):
/// `obj->vt[9].fn(obj + delta, a1)`, returning to `ret`.
pub(crate) fn popup_call_method48(c: &mut Cpu, ret: u32) -> Flow {
    c.cycles += 5;
    c.g[V0][0] = Addr(r32(c, A2).wrapping_add(8)).lw(c);
    c.g[A0][0] = Addr(r32(c, V0).wrapping_add(0x48)).lh(c);
    c.g[V1][0] = Addr(r32(c, V0).wrapping_add(0x4c)).lw(c);
    let method = r32(c, V1);
    c.g[A0][0] = sx(r32(c, A2).wrapping_add(r32(c, A0)));
    call_ptr(c, method, ret)
}

/// A UIState-derived destructor that stores the vtable word `vtable` at
/// `self+8` and then runs `UIState_dtor(self)`, returning to `ret`.
pub(crate) fn ui_state_dtor_store(c: &mut Cpu, vtable: u64, ret: u32) -> Flow {
    c.cycles += 10;
    let frame = Frame::open(c, 0x10);
    frame.save_ra(c, 0);
    c.g[V1][0] = c.g[A0][0];
    c.g[V0][0] = vtable;
    let value = c.g[V0][0];
    Addr(r32(c, V1).wrapping_add(8)).sw(c, value);
    call_ptr(c, UI_STATE_DTOR, ret)?;
    frame.restore_ra(c, 0);
    frame.close(c);
    Ok(())
}

/// A UIState-derived constructor shell: `UIState_ctor(self, 0)`, then the
/// vtable word `vtable` at `self+8`. Returns to `ret` (the caller's).
pub(crate) fn ui_state_ctor_store(c: &mut Cpu, vtable: u64, ret: u32) -> Flow {
    c.cycles += 14;
    let frame = Frame::open(c, 0x20);
    c.g[A1][0] = 0;
    frame.save(c, S0, 0x10);
    frame.save_ra(c, 0);
    c.g[S0][0] = c.g[A0][0];
    call_ptr(c, UI_STATE_CTOR, ret)?;
    c.g[V1][0] = vtable;
    c.g[V0][0] = c.g[S0][0];
    frame.restore_ra(c, 0);
    let value = c.g[V1][0];
    Addr(r32(c, S0).wrapping_add(8)).sw(c, value);
    frame.restore(c, S0, 0x10);
    frame.close(c);
    Ok(())
}

