/// `NetFEState_dtor` (0x1a85d0).
pub fn cfe_state_create_step2_dtor(c: &mut Cpu) {
    guest(c, |c| {
        oc965_vtable_dtor(c, 0x7a50, 0x001a_85d0, 0x001e_0dc4)
    })
}

