    /// An inbox with `count` entries whose ids come from `ids`.
    pub(crate) fn inbox(c: &mut Cpu, at: u32, count: u8, ids: &[u32]) {
        clear_3(c, at, 0x40);
        c.bus.write8(at + 0xcc, count);
        for (i, &id) in ids.iter().enumerate() {
            w(c, at + 8 * i as u32, id);
        }
    }

