    /// Run a guest helper during setup; its `v0`.
    pub(crate) fn call0(c: &mut Cpu, f: GuestFn, args: &[u64]) -> u64 {
        for (i, a) in args.iter().enumerate() {
            c.g[[A0, A1, A2, A3][i]][0] = *a;
        }
        c.g[RA][0] = crate::difftest::RA as u64;
        f(c);
        c.g[V0][0]
    }

