    pub(crate) const SEEDS_11: u32 = 240;

    /// Gate word of this module's gated fakes (its own word in the machine).
    pub(crate) const CTRL: u32 = DATA + 0x7e_0000;

    pub(crate) const MAGIC: u32 = 0x4f43_3948;

    /// Forced-result mailboxes: one word per fake address at `MAIL + (addr & 0xffc)`.
    pub(crate) const MAIL: u32 = DATA + 0x7f_0000;

    /// Fixture objects, clear of the fakes' pointers (`DATA..DATA+0x40000`)
    /// and of the call log (`DATA+0x100000`).
    pub(crate) const SELF: u32 = DATA + 0x50_0000;

    pub(crate) const WIDGET: u32 = DATA + 0x50_1000;

    pub(crate) const WIDGET_VT: u32 = DATA + 0x50_1100;

    pub(crate) const ENG: u32 = DATA + 0x50_2000;

    pub(crate) const SNDO: u32 = DATA + 0x50_3000;

    pub(crate) const SND_VT: u32 = DATA + 0x50_3100;

    pub(crate) const DEF_VT: u32 = DATA + 0x50_3200;

    pub(crate) const OBJ_2: u32 = DATA + 0x50_4000;

    pub(crate) const OBJ_VT: u32 = DATA + 0x50_4100;

    pub(crate) const SCREEN: u32 = DATA + 0x50_5000;

    /// A zeroed buffer: the empty hash name the gp globals point at.
    pub(crate) const NAME: u32 = DATA + 0x51_0000;

    /// Method targets outside the function table (the miss hook answers).
    pub(crate) const F_WIDGET: u32 = fakes::FAKE + 0x60;

    pub(crate) const F_OBJ: u32 = fakes::FAKE + 0x30;

    pub(crate) const F_SND: u32 = fakes::FAKE + 0x50;

    pub(crate) const F_DEF: u32 = fakes::FAKE + 0x70;

    pub(crate) fn oc948_mail(addr: u32) -> u32 {
        MAIL + (addr & 0xffc)
    }

    /// Make the fake for `addr` return `v` (0 is a real zero result).
    pub(crate) fn oc948_force(c: &mut Cpu, addr: u32, v: u32) {
        c.bus.write32(oc948_mail(addr), v.wrapping_add(3));
    }

    /// The fake callee: logs the call, then returns the forced result of
    /// its mailbox unless it unwound.
    pub(crate) fn oc948_fake_call(c: &mut Cpu, addr: u32) {
        let ra = c.g[RA][0] as u32;
        let mail = c.bus.read32(oc948_mail(addr));
        fakes::fake_call(c, addr);
        if c.pc == ra && mail != 0 {
            c.g[V0][0] = (mail - 3) as u64;
        }
    }

    /// The miss hook of this module's machines (targets outside the table).
    pub(crate) fn oc948_miss(c: &mut Cpu, target: u32) {
        oc948_fake_call(c, target)
    }

    /// Gated fakes for the callees with override slots: with the gate off they
    /// run the body they replaced.
    macro_rules! oc948_fakes {
        ($(($fake:ident, $prev:ident, $slot:expr, $gen:expr, $addr:expr)),* $(,)?) => {
            $(
                static $prev: AtomicUsize = AtomicUsize::new(0);
                fn $fake(c: &mut Cpu) {
                    if c.bus.read32(CTRL) != MAGIC {
                        return fakes::fall_back(c, &$prev, $gen);
                    }
                    oc948_fake_call(c, $addr);
                }
            )*
            fn oc948_install() {
                use std::ptr::addr_of_mut;
                $( fakes::hook(addr_of_mut!($slot), $fake, &$prev); )*
            }
        };
    }

