    /// `hidePass` through a widget whose vtable slot is the real leaf at
    /// `0x1406c0` (returns 0). The vtable's `s16` at `+0x48` varies in sign
    /// and value, so the widget pointer moves with it.
    #[test]
    fn cfe_state_mountain_room_hide_widget48_matches() {
        check(
            ee::s04::f_001e00e0__generated,
            cfe_state_mountain_room_hide_widget48,
            200,
            &|c, seed| {
                let mut r = machine(c, seed, 0x001e_00e0, 0);
                let widget = DATA + 0x3000;
                let vtable = DATA + 0x3100;
                let off = if seed % 2 == 0 {
                    r.next_u32() & 0x7fff
                } else {
                    0x8000 | (r.next_u32() & 0x7fff)
                };
                c.g[A0][0] = (DATA + 0x2000) as u64;
                c.bus.write32(DATA + 0x2048, widget);
                c.bus.write32(widget + 0x8, vtable);
                c.bus.write16(vtable + 0x48, off as u16);
                c.bus.write32(vtable + 0x4c, 0x0014_06c0);
                c.pc = 0x001e_00e0;
            },
        );
    }

    /// Gate words of this module's two `UIState` fakes, in each machine's own
    /// RAM (a unique place above the fixture's usual data).
    pub(crate) const OC952_GATE_CTOR: u32 = DATA + 0x0029_5000;

    pub(crate) const OC952_GATE_DTOR: u32 = DATA + 0x0029_5004;

    pub(crate) const OC952_MAGIC: u32 = 0x0952_6a7e;

    pub(crate) static OC952_PREV_CTOR: AtomicUsize = AtomicUsize::new(0);

    pub(crate) static OC952_PREV_DTOR: AtomicUsize = AtomicUsize::new(0);

    /// The `UIState_ctor` slot's test fake: with its gate on it only logs the
    /// call; with the gate off it runs the body the slot held before.
    pub(crate) fn oc952_fake_ui_ctor(c: &mut Cpu) {
        if c.bus.read32(OC952_GATE_CTOR) != OC952_MAGIC {
            return fakes::fall_back(c, &OC952_PREV_CTOR, ee::s13::f_0039e2a0__generated);
        }
        let ra = c.g[RA][0] as u32;
        fakes::fake(c, OC952_UISTATE_CTOR, ra);
    }

    /// The `UIState_dtor` slot's test fake, gated like [`oc952_fake_ui_ctor`].
    pub(crate) fn oc952_fake_ui_dtor(c: &mut Cpu) {
        if c.bus.read32(OC952_GATE_DTOR) != OC952_MAGIC {
            return fakes::fall_back(c, &OC952_PREV_DTOR, ee::s13::f_0039e390__generated);
        }
        let ra = c.g[RA][0] as u32;
        fakes::fake(c, OC952_UISTATE_DTOR, ra);
    }

    /// A machine with the two base-state fakes hooked (once per process).
    pub(crate) fn oc952_machine(c: &mut Cpu, seed: u32, salt: u64) -> Rng {
        fakes::hook(
            addr_of_mut!(ee::s13::OVERRIDE_0039E2A0),
            oc952_fake_ui_ctor,
            &OC952_PREV_CTOR,
        );
        fakes::hook(
            addr_of_mut!(ee::s13::OVERRIDE_0039E390),
            oc952_fake_ui_dtor,
            &OC952_PREV_DTOR,
        );
        machine(c, seed, salt, 2)
    }

    /// A constructor case: the object at `DATA + 0x2000`, the base ctor faked
    /// (logged), and `a1` scrambled (the port must set it to 0 itself).
    pub(crate) fn oc952_ctor_case(generated: GuestFn, hand: GuestFn, salt: u64) {
        check(generated, hand, 60, &|c, seed| {
            let mut r = oc952_machine(c, seed, salt);
            c.bus.write32(OC952_GATE_CTOR, OC952_MAGIC);
            c.g[A0][0] = sx(DATA + 0x2000);
            c.g[A1][0] = r.next_u32() as u64;
        });
    }

    /// A destructor case: the object at `DATA + 0x2000`, the base dtor faked
    /// (logged), and random flags, which must pass through unchanged.
    pub(crate) fn oc952_dtor_case(generated: GuestFn, hand: GuestFn, salt: u64) {
        check(generated, hand, 60, &|c, seed| {
            let mut r = oc952_machine(c, seed, salt);
            c.bus.write32(OC952_GATE_DTOR, OC952_MAGIC);
            c.g[A0][0] = sx(DATA + 0x2000);
            c.g[A1][0] = r.next_u32() as u64;
        });
    }

    /// `StrHash` of the NUL-terminated name at `at` in the game image.
    pub(crate) fn oc952_name_hash(c: &mut Cpu, at: u32) -> u32 {
        let mut name = Vec::new();
        for k in 0..64 {
            let b = c.bus.read8(at + k);
            if b == 0 {
                break;
            }
            name.push(b);
        }
        str_hash(&name)
    }

