    pub(crate) const OC956_BOX_IF8: u32 = 3;

    pub(crate) const OC956_BOX_IFD: u32 = 4;

    pub(crate) const OC956_BOX_PLAYER: u32 = 5;

    pub(crate) const OC956_BOX_OBJ_CALLS: u32 = 6;

    // Fixture layout (inside DATA..DATA+0xfffff, above the fakes' pointers).
    pub(crate) const OC956_SELF: u32 = DATA + 0x8_0000;

    pub(crate) const OC956_SCREEN: u32 = DATA + 0x8_0200;

    pub(crate) const OC956_OBJ: u32 = DATA + 0x8_0300;

    pub(crate) const OC956_OBJ_VT: u32 = DATA + 0x8_0400;

    pub(crate) const OC956_IF8: u32 = DATA + 0x8_0500;

    pub(crate) const OC956_IFD: u32 = DATA + 0x8_0600;

