    /// Gate open, the soup filled (half small numbers 0..8, half soup pointers).
    pub(crate) fn oc960_open(c: &mut Cpu, r: &mut crate::difftest::Rng) {
        c.bus.write32(OC960_CTRL, OC960_MAGIC);
        for i in 0..OC960_SOUP_BYTES / 4 {
            let w = r.next_u32();
            let v = if w & 1 == 0 {
                (w >> 8) % 8
            } else {
                OC960_SOUP + ((w >> 8) & (OC960_SOUP_BYTES - 4))
            };
            c.bus.write32(OC960_SOUP + 4 * i, v);
        }
    }

    /// `OVScreenFinalStandings_TransitionIn(self)`: the pending flag at `+0x9c` (clear: nothing
    /// to do), the event kind bytes at 0x535bc8 + 0x48 / 0x49 (selecting the jump-table arm and
    /// the rider / location branches), the soup for the world / rider-interface chains.
    #[test]
    fn ov_screen_final_standings_transition_in_matches() {
        oc960_install_fakes();
        fakes::covered(
            ee::s04::f_001e6718__generated,
            ov_screen_final_standings_transition_in,
            400,
            &|c, seed| {
                let mut r = machine(c, seed, 0x1e6718, 40);
                elf_image(c);
                oc960_open(c, &mut r);
                let this = DATA + 0x1000;
                c.bus
                    .write32(this + 0x9c, if seed % 7 == 0 { 0 } else { 1 });
                c.bus.write32(this + 0x40, OC960_SOUP + 0x80);
                let world = OC960_SOUP + 0x400;
                c.bus.write32(GAME_GP - 0x848, world);
                c.bus.write32(
                    GAME_GP - 0xfb4,
                    if seed % 3 == 0 { 0 } else { OC960_SOUP + 0x300 },
                );
                c.bus.write8(0x0053_5bc8 + 0x48, (seed % 8) as u8);
                c.bus.write8(0x0053_5bc8 + 0x49, ((seed / 8) % 4) as u8);
                if seed % 5 == 0 {
                    oc960_force(c, 10, 0);
                }
                c.g[A0][0] = sx(this);
                c.pc = 0x001e_6718;
            },
        );
    }

    /// Gate word of this module's callee fakes (in the machine's own RAM) and
    /// its value; the mailbox words (`OC961_CTRL + 0x10 + 4 * k`) hold what the
    /// fakes answer.
    pub(crate) const OC961_CTRL: u32 = DATA + 0x2d_0000;

    pub(crate) const OC961_MAGIC: u32 = 0x4f43_3936 + 1;

    pub(crate) fn oc961_mail(c: &mut Cpu, k: u32, v: u32) {
        c.bus.write32(OC961_CTRL + 0x10 + 4 * k, v);
    }

    /// Gated fakes for the callees that have an override slot. `mode` 0:
    /// only logs the call; 1: returns bit `call index & 31` of mailbox word
    /// `k`; 2: returns mailbox word `k`; 3: a hash compare: returns word `k+1`
    /// on call index `word k`, else a different value.
    macro_rules! oc961_fakes {
        ($(($fake:ident, $prev:ident, $slot:expr, $gen:expr, $addr:expr, $mode:expr, $k:expr)),* $(,)?) => {
            $(
                static $prev: AtomicUsize = AtomicUsize::new(0);
                fn $fake(c: &mut Cpu) {
                    if c.bus.read32(OC961_CTRL) != OC961_MAGIC {
                        return fakes::fall_back(c, &$prev, $gen);
                    }
                    let n = c.bus.read32(fakes::LOG_COUNT);
                    fakes::fake_call(c, $addr);
                    if c.pc >> 16 == 0xdead {
                        return;
                    }
                    let word = c.bus.read32(OC961_CTRL + 0x10 + 4 * $k);
                    if $mode == 1 {
                        c.g[V0][0] = ((word >> (n & 31)) & 1) as u64;
                    } else if $mode == 2 {
                        c.g[V0][0] = sx(word);
                    } else if $mode == 3 {
                        let h = c.bus.read32(OC961_CTRL + 0x14 + 4 * $k);
                        c.g[V0][0] = sx(if n == word { h } else { h ^ (n + 1) });
                    }
                }
            )*
            pub(crate) fn oc961_install_fakes() {
                use std::ptr::addr_of_mut;
                $( fakes::hook(addr_of_mut!($slot), $fake, &$prev); )*
            }
        };
    }

