    /// Gate word: the fakes answer only in a machine that writes `OC967_MAGIC`
    /// there; other tests' machines fall back to the real bodies.
    pub(crate) const OC967_GATE: u32 = DATA + 0x20_0000;

    pub(crate) const OC967_MAGIC: u32 = 0x0967_c0de;

    /// Answer words: `OC967_ANSWER + 4 * k` is what fake `k` returns in v0.
    pub(crate) const OC967_ANSWER: u32 = OC967_GATE + 0x10;

    pub(crate) const K_BE: u32 = 0;

    pub(crate) const K_INTERFACE: u32 = 1;

    pub(crate) const K_HUMAN_RIDER: u32 = 2;

    pub(crate) const K_RIDER_CHAR: u32 = 3;

    pub(crate) const K_PEAK_LOCKED: u32 = 4;

    pub(crate) const K_MONEY: u32 = 5;

    pub(crate) const K_MONEY_CMP: u32 = 6;

    pub(crate) const K_CMP_157: u32 = 7;

    /// Bit mask: `IsFlagSet(id)` is bit `id & 31` of this word.
    pub(crate) const K_FLAG_MASK: u32 = 8;

    pub(crate) const K_CHAR_FLAG: u32 = 15;

    /// Bit mask: `IsMessageOfType(type, _)` is bit `type & 31` of this word.
    pub(crate) const K_OF_TYPE_MASK: u32 = 12;

    pub(crate) const K_INBOX: u32 = 13;

    pub(crate) const K_PICK_VARIANT: u32 = 16;

    pub(crate) const K_RAND: u32 = 18;

    pub(crate) const K_TABLE_OBJ: u32 = 19;

    pub(crate) const K_OBJ_NEXT: u32 = 20;

    /// Fixture addresses (the replay chain `gp - 0x848` -> world -> +0x84 ->
    /// +0x28 holds the replay length).
    pub(crate) const WORLD: u32 = DATA + 0x1000;

    pub(crate) const P1: u32 = DATA + 0x1100;

    pub(crate) const P2: u32 = DATA + 0x1200;

    pub(crate) const INBOX: u32 = DATA + 0x1300;

    pub(crate) const IFACE: u32 = DATA + 0x1400;

    pub(crate) const BE: u32 = DATA + 0x1500;

    pub(crate) const P3: u32 = DATA + 0x1600;

    pub(crate) const OBJ_3: u32 = DATA + 0x1700;

    pub(crate) const OBJ2_2: u32 = DATA + 0x1800;

    pub(crate) const VT_2: u32 = DATA + 0x1900;

    /// The aggression and group tables (0x14 bytes per entry) at `0x441630`, and
    /// the message table of `PostMessage` (`0x4c6c08 + 0x18 * msg`).
    pub(crate) const AGGRESSION_TABLE: u32 = 0x0044_1630;

    pub(crate) const MSG_TABLE: u32 = 0x004c_6c08;

    /// A fake answering with mailbox word `k` in v0, gated on `OC967_GATE`.
    macro_rules! oc967_fake {
        ($name:ident, $k:expr, $gen:path) => {
            fn $name(c: &mut Cpu) {
                if c.bus.read32(OC967_GATE) != OC967_MAGIC {
                    return fakes::fall_back(c, fakes::prev_cell($name), $gen);
                }
                c.g[V0][0] = c.bus.read32(OC967_ANSWER + 4 * $k) as u64;
                c.pc = c.g[RA][0] as u32;
            }
        };
    }

